mod lazy;
#[path="../hec_native2lp_20261116/graph.rs"] mod eager;
use hec_native_ic::{fp::Fp,rng::Rng};
use eager::Row;
fn add(a:u64,b:u64,p:u64)->u64{((a as u128+b as u128)%p as u128)as u64}
fn mul(a:u64,b:u64,p:u64)->u64{(a as u128*b as u128%p as u128)as u64}
fn pow(mut a:u64,mut b:u64,p:u64)->u64{let mut z=1;while b>0{if b&1!=0{z=mul(z,a,p)}a=mul(a,a,p);b>>=1;}z}
fn rank(mut a:Vec<Vec<u64>>,cols:usize,p:u64)->usize{let mut r=0;for c in 0..cols{let Some(q)=(r..a.len()).find(|&i|a[i][c]!=0)else{continue};a.swap(r,q);let inv=pow(a[r][c],p-2,p);for j in c..cols{a[r][j]=mul(a[r][j],inv,p);}for i in r+1..a.len(){let b=a[i][c];for j in c..cols{a[i][j]=add(a[i][j],p-mul(b,a[r][j],p),p);}}r+=1;if r==a.len(){break}}r}
fn dense(r:&Row,d:usize)->Vec<u64>{let mut x=vec![0;d];for&(i,a)in r{x[i as usize]=a;}x}
fn dot(a:&[u64],b:&[u64],p:u64)->u64{a.iter().zip(b).fold(0,|z,(&a,&b)|add(z,mul(a,b,p),p))}
fn check_ops(g:&lazy::Graph,rows:&[Row],d:usize,p:u64,rng:&mut Rng){let x:Vec<_>=(0..d).map(|_|rng.below(p)).collect();let y:Vec<_>=(0..rows.len()).map(|_|rng.below(p)).collect();let rx=g.circuit.apply(&x);let ty=g.circuit.transpose(&y);let want:Vec<_>=rows.iter().map(|r|dot(&dense(r,d),&x,p)).collect();assert_eq!(rx,want,"forward_operator");let mut t=vec![0;d];for(r,&a)in rows.iter().zip(&y){for&(i,b)in r{t[i as usize]=add(t[i as usize],mul(a,b,p),p);}}assert_eq!(ty,t,"transpose_operator");assert_eq!(dot(&rx,&y,p),dot(&x,&ty,p),"adjoint_identity");}
fn prefix(g:&lazy::Graph,rows:&[Row],inputs:&[Vec<u64>],n:usize,d:usize,p:u64){let rm=rank(inputs.to_vec(),n+d,p);let rl=rank(inputs.iter().map(|r|r[..n].to_vec()).collect(),n,p);let rr=rank(rows.iter().map(|r|dense(r,d)).collect(),d,p);assert_eq!(rr,rm-rl,"complete_elimination_rank");assert_eq!(g.links,rl,"pivot_count_equals_L_rank");assert_eq!(rows.len(),inputs.len()-rl,"zero_and_dependent_rows_retained");let mut augmented=inputs.to_vec();for r in rows{let mut a=vec![0;n];a.extend(dense(r,d));augmented.push(a);}assert_eq!(rank(augmented,n+d,p),rm,"emitted_rowspace_containment");}
fn stream(p:u64,seed:u64){let(n,d)=(8,5);let mut a=eager::Graph::new(n,d-1,p);let mut b=lazy::Graph::new(n,d,p);let mut rng=Rng::new(seed);let mut rows=vec![];let mut inputs=vec![];for _ in 0..40{let degree=rng.below(3);let large:Vec<_>=(0..degree).map(|_|(1+rng.below(n as u64)as usize,1+rng.below(p-1))).collect();let row:Row=(0..d).filter_map(|j|{let v=rng.below(p);if v==0{None}else{Some((j as u32,v))}}).collect();let mut inp=vec![0;n];for&(j,v)in &large{inp[j-1]=add(inp[j-1],v,p);}inp.extend(dense(&row,d));inputs.push(inp);let x=a.insert(&large,row.clone());let y=b.insert(&large,row);assert_eq!(x.is_some(),y.is_some());if let Some(id)=y{let out=b.circuit.expand(id);assert_eq!(Some(out.clone()),x,"eager_deferred_exact_row");rows.push(out);}prefix(&b,&rows,&inputs,n,d,p);check_ops(&b,&rows,d,p,&mut rng);}
 for i in 0..d{let mut x=vec![0;d];x[i]=1;let z=b.circuit.apply(&x);let want:Vec<_>=rows.iter().map(|r|dense(r,d)[i]).collect();assert_eq!(z,want,"basis_forward");}for j in 0..rows.len(){let mut y=vec![0;rows.len()];y[j]=1;assert_eq!(b.circuit.transpose(&y),dense(&rows[j],d),"basis_transpose");}println!("STREAM p={p} seed={seed} prefixes=40 rows={} nodes={} links={} complete_rowspace=true forward_transpose_exact=true",rows.len(),b.circuit.nodes(),b.links);}
fn directed(){let p=101;let mut a=eager::Graph::new(3,2,p);let mut b=lazy::Graph::new(3,3,p);let cases=vec![(vec![(1,1),(1,100)],vec![(0,1)]),(vec![(1,3),(2,7)],vec![(1,2)]),(vec![(1,2),(2,5)],vec![(2,3)]),(vec![(1,1),(2,1)],vec![]),(vec![(3,9)],vec![(0,4)]),(vec![],vec![])];let mut rows=vec![];let mut inputs=vec![];for(large,row)in cases{let mut inp=vec![0;3];for&(j,v)in &large{inp[j-1]=add(inp[j-1],v,p);}inp.extend(dense(&row,3));inputs.push(inp);let x=a.insert(&large,row.clone());let y=b.insert(&large,row);assert_eq!(x.is_some(),y.is_some());if let Some(id)=y{assert_eq!(Some(b.circuit.expand(id)),x);rows.push(b.circuit.expand(id));}prefix(&b,&rows,&inputs,3,3,p);}assert!(a.stats.anchors>0&&a.stats.anchored_cycles>0);
 let mut c=lazy::Circuit::new(2,p);let leaf=c.leaf(vec![(0,3),(1,5)]);let shared=c.combine(leaf,7,leaf,9);c.roots=vec![shared,shared,0];assert_eq!(c.apply(&[2,4]),vec![12,12,0]);assert_eq!(c.transpose(&[2,3,9]),vec![38,97]);println!("DIRECTED repeated_endpoint_cancellation=true unbalanced_anchor=true anchored_cycle=true nonunit=true repeated_roots_and_children=true zero_rows=true");}
fn fixture(){let(n,d,p)=(512,256,65537);let mut a=eager::Graph::new(n,d-1,p);let mut b=lazy::Graph::new(n,d,p);let mut nnz=0;let mut count=0;let mut insert=|large:Vec<(usize,u64)>,row:Row|{let x=a.insert(&large,row.clone());let y=b.insert(&large,row);assert_eq!(x.is_some(),y.is_some());if let Some(id)=y{let out=b.circuit.expand(id);assert_eq!(Some(out.clone()),x);nnz+=out.len();count+=1;}};insert(vec![(1,1)],vec![(0,1)]);for i in 2..=n{insert(vec![(i,1),(i-1,p-1)],vec![((i%d)as u32,1)]);}for i in 1..=n{insert(vec![(i,1)],vec![]);}drop(insert);let bound=b.circuit.leaf_entries+2*b.circuit.sums();println!("FILL_FIXTURE vertices={n} retained={d} outputs={count} expanded_nnz={nnz} circuit_nodes={} sums={} leaf_entries={} apply_mul_upper_bound={bound} transpose_mul_upper_bound={bound} exact_rows=true synthetic_not_curve=true",b.circuit.nodes(),b.circuit.sums(),b.circuit.leaf_entries);}
fn main(){directed();for p in[3,5,101]{for seed in 1..=12{stream(p,seed);}}fixture();println!("PASS streams=36 prefixes=1440 full_operator_basis_checks=true complete_elimination_span=true timing_claim=false");}
